package co.elhacker.maquinitas.servlet;
import co.elhacker.maquinitas.dao.TiendaDAO;import co.elhacker.maquinitas.util.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet("/billetera") public class BilleteraServlet extends HttpServlet {private final TiendaDAO dao=new TiendaDAO();protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{Integer u=Autenticacion.usuario(q);if(u==null){Json.enviar(r,401,Map.of("success",false,"message","Inicia sesión."));return;}try{Map<String,Object>d=dao.billetera(u);d.put("success",true);Json.enviar(r,200,d);}catch(Exception e){getServletContext().log("Error billetera",e);Json.enviar(r,500,Map.of("success",false,"message","No se pudo consultar la billetera. Ejecuta la migración SQL."));}}}
